import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ClientSearchSchema = z.object({
  q: z.string().min(1).max(100),
  limit: z.coerce.number().int().min(1).max(20).default(10),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ClientSearchSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { q, limit } = parsed.data

  try {
    const supabase = await createClient()

    // N3: Use fts column (tsvector) for safe full-text search rather than
    // interpolating `q` into .or() string syntax. Supabase PostgREST treats
    // commas and parentheses in .or() as grammar, making interpolation injectable.
    // textSearch() binds `q` as a parameter — no injection surface.
    const { data, error } = await supabase
      .from('clients')
      .select('id, first_name, last_name, email, phone, total_sessions, last_visit_at, tags')
      .eq('studio_id', authUser.studioId)
      .textSearch('fts', q, { type: 'websearch' })
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(limit)

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'client search failed')
      return NextResponse.json({ error: 'Search failed' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'clients search unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

