import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ClientListSchema = z.object({
  q: z.string().max(200).optional(),
  tags: z.string().optional(), // comma-separated slugs
  vip: z.coerce.boolean().optional(),
  inactive: z.coerce.boolean().optional(),
  no_show: z.coerce.boolean().optional(),
  spending_min: z.coerce.number().int().min(0).optional(),
  spending_max: z.coerce.number().int().min(0).optional(),
  archived: z.coerce.boolean().default(false),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(25),
  sort: z.enum(['last_visit_at', 'total_spent_cents', 'total_sessions', 'created_at']).default('last_visit_at'),
  order: z.enum(['asc', 'desc']).default('desc'),
})

const CreateClientSchema = z.object({
  first_name: z.string().min(1, 'First name is required').max(100),
  last_name: z.string().max(100).optional().nullable(),
  email: z.string().email('Enter a valid email address').optional().nullable(),
  phone: z.string().regex(/^[+\d][\d\s\-().]{5,20}$/, 'Enter a valid phone number').optional().nullable(),
  date_of_birth: z.string().optional().nullable(),
  address: z
    .object({
      street: z.string().optional(),
      city: z.string().optional(),
      state: z.string().optional(),
      postal_code: z.string().optional(),
      country: z.string().optional(),
    })
    .optional()
    .nullable(),
  source: z.string().optional().nullable(),
  referral_source: z.string().optional().nullable(),
  tags: z.array(z.string()).max(10, 'Maximum 10 tags per client').default([]),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).default('email'),
  consent_minor: z.boolean().default(false),
  // Consent prefs
  marketing_email: z.boolean().default(false),
  marketing_sms: z.boolean().default(false),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ClientListSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { q, tags, vip, inactive, no_show, spending_min, spending_max, archived, page, per_page, sort, order } = parsed.data

  try {
    const supabase = await createClient()

    let query = supabase
      .from('clients')
      .select(
        'id, first_name, last_name, email, phone, tags, last_visit_at, total_spent_cents, total_sessions, no_show_count, source, preferred_contact, archived_at, created_at',
        { count: 'exact' }
      )
      .eq('studio_id', authUser.studioId)

    // Archive filter
    if (archived) {
      query = query.not('archived_at', 'is', null)
    } else {
      query = query.is('archived_at', null)
    }

    // Full-text search using the fts generated column
    if (q) {
      query = query.textSearch('fts', q, { type: 'websearch' })
    }

    // Tag filter (clients must have ALL specified tags)
    if (tags) {
      const tagArray = tags.split(',').filter(Boolean)
      if (tagArray.length > 0) {
        query = query.contains('tags', tagArray)
      }
    }

    // VIP filter — tag slug "vip"
    if (vip) {
      query = query.contains('tags', ['vip'])
    }

    // Inactive filter — last_visit_at < 90 days ago OR null
    if (inactive) {
      const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
      query = query.or(`last_visit_at.lt.${ninetyDaysAgo},last_visit_at.is.null`)
    }

    // No-show filter
    if (no_show) {
      query = query.gt('no_show_count', 0)
    }

    // Spending range filter (in cents)
    if (spending_min !== undefined) {
      query = query.gte('total_spent_cents', spending_min)
    }
    if (spending_max !== undefined) {
      query = query.lte('total_spent_cents', spending_max)
    }

    // Sort & pagination
    query = query
      .order(sort, { ascending: order === 'asc', nullsFirst: false })
      .range((page - 1) * per_page, page * per_page - 1)

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'client list failed')
      return NextResponse.json({ error: 'Failed to fetch clients' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'clients GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateClientSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { marketing_email, marketing_sms, ...clientData } = parsed.data

  try {
    const supabase = await createClient()

    const { data: client, error } = await supabase
      .from('clients')
      .insert({
        ...clientData,
        studio_id: authUser.studioId,
      })
      .select()
      .single()

    if (error) {
      // Unique constraint on email per studio
      if (error.code === '23505') {
        return NextResponse.json(
          { error: 'A client with this email already exists in your studio.' },
          { status: 409 }
        )
      }
      logger.error({ err: error, studioId: authUser.studioId }, 'client create failed')
      return NextResponse.json({ error: 'Failed to create client' }, { status: 500 })
    }

    // Upsert consent preferences
    if (marketing_email || marketing_sms) {
      await supabase.from('client_consent_preferences').upsert(
        {
          studio_id: authUser.studioId,
          client_id: client.id,
          marketing_email,
          marketing_sms,
          consented_at: new Date().toISOString(),
        },
        { onConflict: 'client_id' }
      )
    }

    return NextResponse.json({ data: client }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'clients POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const UpdateClientSchema = z.object({
  first_name: z.string().min(1).max(100).optional(),
  last_name: z.string().max(100).optional().nullable(),
  email: z.string().email().optional().nullable(),
  phone: z.string().regex(/^[+\d][\d\s\-().]{5,20}$/).optional().nullable(),
  date_of_birth: z.string().optional().nullable(),
  address: z
    .object({
      street: z.string().optional(),
      city: z.string().optional(),
      state: z.string().optional(),
      postal_code: z.string().optional(),
      country: z.string().optional(),
    })
    .optional()
    .nullable(),
  source: z.string().optional().nullable(),
  referral_source: z.string().optional().nullable(),
  tags: z.array(z.string()).max(10).optional(),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).optional(),
  consent_minor: z.boolean().optional(),
  notes: z.string().optional().nullable(),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

async function verifyClientOwnership(supabase: Awaited<ReturnType<typeof createClient>>, clientId: string, studioId: string) {
  const { data, error } = await supabase
    .from('clients')
    .select('id')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()
  return !error && data !== null
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('clients')
      .select('*')
      .eq('id', id)
