  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  // Only owner role can hard-delete
  if (!['owner'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()
    const owns = await verifyClientOwnership(supabase, id, authUser.studioId)
    if (!owns) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    // Soft-archive instead of hard delete (set archived_at)
    const { error } = await supabase
      .from('clients')
      .update({ archived_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.error({ err: error, clientId: id }, 'client DELETE failed')
      return NextResponse.json({ error: 'Failed to archive client' }, { status: 500 })
    }

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'client DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

