import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'

interface RouteContext {
  params: Promise<{ id: string }>
}

// Shape returned by get_client_profile RPC
export type ClientProfile = Database['public']['Tables']['clients']['Row'] & {
  pinned_notes: Array<{
    id: string
    category: string
    body: string
    is_pinned: boolean
    author_id: string | null
    created_at: string
  }>
  consent_preferences: Database['public']['Tables']['client_consent_preferences']['Row'] | null
  booking_count: number
  photo_count: number
  file_count: number
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data, error } = await supabase.rpc('get_client_profile', { p_client_id: id })

    if (error) {
      logger.error({ err: error, clientId: id }, 'get_client_profile RPC failed')
      return NextResponse.json({ error: 'Failed to fetch client profile' }, { status: 500 })
    }

    if (!data) {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }

    // RPC returns jsonb — check for error keys in the payload
    const payload = data as Record<string, unknown>
    if (payload.error === 'not_found') {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }
    if (payload.error === 'unauthenticated') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    return NextResponse.json({ data: data as ClientProfile })
  } catch (err) {
    logger.error({ err }, 'client profile GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

