      return NextResponse.json({ error: 'A tag with this name already exists.' }, { status: 409 })
    }

    const { data, error } = await supabase
      .from('client_tags')
      .insert({
        ...parsed.data,
        studio_id: authUser.studioId,
        // slug not in types — the migration uses name directly as the tag value stored in clients.tags[]
      })
      .select()
      .single()

    if (error) {
      if (error.code === '23505') {
        return NextResponse.json({ error: 'A tag with this name already exists.' }, { status: 409 })
      }
      logger.error({ err: error }, 'tag create failed')
      return NextResponse.json({ error: 'Failed to create tag' }, { status: 500 })
    }

    // Suppress unused variable warning
    void slugify

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'client-tags POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

