  }

  const parsed = ReorderSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()

    // Update each tag's sort_order individually (Supabase doesn't support bulk upsert with different values easily)
    const updates = parsed.data.items.map(({ id, sort_order }) =>
      supabase
        .from('client_tags')
        .update({ updated_at: new Date().toISOString() })
        .eq('id', id)
        .eq('studio_id', authUser.studioId)
        // sort_order column may not exist in types if not in Sprint 3 schema — use raw update
        // We include it via the spread pattern with explicit cast
        .update({ updated_at: new Date().toISOString(), ...({ sort_order } as Record<string, unknown>) })
    )

    await Promise.all(updates)

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'tag reorder unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ALLOWED_MIME_TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/heic', 'image/heif']
const MAX_FILE_SIZE = 20 * 1024 * 1024 // 20 MB

const FileMetaSchema = z.object({
  client_id: z.string().uuid(),
  file_name: z.string().min(1).max(255),
  mime_type: z.enum(['application/pdf', 'image/jpeg', 'image/png', 'image/heic', 'image/heif']),
  kind: z.enum(['id', 'medical', 'waiver', 'health_form', 'other']).default('other'),
  expires_at: z.string().datetime().optional().nullable(),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const formData = await request.formData()
    const file = formData.get('file') as File | null
    const metaRaw = formData.get('meta') as string | null

    if (!file) return NextResponse.json({ error: 'No file provided' }, { status: 400 })
    if (!metaRaw) return NextResponse.json({ error: 'No metadata provided' }, { status: 400 })

    // Validate file
    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json({ error: 'File must be under 20 MB' }, { status: 400 })
    }
    if (!ALLOWED_MIME_TYPES.includes(file.type)) {
      return NextResponse.json({ error: 'File type not allowed. Use PDF, JPEG, PNG, or HEIC.' }, { status: 400 })
    }

    // Validate metadata
    let meta: unknown
    try {
      meta = JSON.parse(metaRaw)
    } catch {
      return NextResponse.json({ error: 'Invalid metadata JSON' }, { status: 400 })
    }

    const parsed = FileMetaSchema.safeParse(meta)
    if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

    const { client_id, file_name, mime_type, kind, expires_at } = parsed.data

    const supabase = await createClient()

    // Verify client belongs to studio
    const { data: client } = await supabase
      .from('clients')
      .select('id')
      .eq('id', client_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!client) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    // Build storage path: {studio_id}/{client_id}/{uuid}.ext
    const ext = file_name.split('.').pop() ?? 'bin'
    const uuid = crypto.randomUUID()
    const storagePath = `${authUser.studioId}/${client_id}/${uuid}.${ext}`

    // Upload to Supabase Storage
    const fileBuffer = await file.arrayBuffer()
    const { error: uploadError } = await supabase.storage
      .from('client-files')
      .upload(storagePath, fileBuffer, {
        contentType: mime_type,
        upsert: false,
      })

    if (uploadError) {
      logger.error({ err: uploadError }, 'client file storage upload failed')
      return NextResponse.json({ error: 'Failed to upload file' }, { status: 500 })
    }

    // Insert DB record
    const { data, error } = await supabase
      .from('client_files')
      .insert({
        studio_id: authUser.studioId,
        client_id,
        storage_path: storagePath,
        file_name,
        mime_type,
        size_bytes: file.size,
        kind,
        uploaded_by: authUser.user.id,
        expires_at: expires_at ?? null,
      })
      .select()
      .single()

    if (error) {
      // Clean up the uploaded file if DB insert fails
      await supabase.storage.from('client-files').remove([storagePath])
      logger.error({ err: error }, 'client file DB insert failed')
      return NextResponse.json({ error: 'Failed to save file record' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'client-files POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data: fileRecord, error } = await supabase
      .from('client_files')
      .select('storage_path, file_name')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !fileRecord) {
      return NextResponse.json({ error: 'File not found' }, { status: 404 })
    }

    // Generate 1-hour signed URL (never expose storage_path directly)
    const { data: signed, error: signError } = await supabase.storage
      .from('client-files')
      .createSignedUrl(fileRecord.storage_path, 3600)

    if (signError || !signed) {
      logger.error({ err: signError, fileId: id }, 'signed URL generation failed')
      return NextResponse.json({ error: 'Failed to generate download URL' }, { status: 500 })
    }

    return NextResponse.json({ url: signed.signedUrl, file_name: fileRecord.file_name })
  } catch (err) {
    logger.error({ err }, 'client-files GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  if (!['owner', 'admin', 'receptionist'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data: fileRecord, error: fetchError } = await supabase
      .from('client_files')
      .select('storage_path')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (fetchError || !fileRecord) {
      return NextResponse.json({ error: 'File not found' }, { status: 404 })
    }

    // Delete from storage
    await supabase.storage.from('client-files').remove([fileRecord.storage_path])

    // Delete DB record
    const { error } = await supabase
      .from('client_files')
      .delete()
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.error({ err: error, fileId: id }, 'client file DELETE failed')
      return NextResponse.json({ error: 'Failed to delete file' }, { status: 500 })
    }

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'client-files DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const CommsListSchema = z.object({
  client_id: z.string().uuid().optional(),
  channel: z.enum(['email', 'sms', 'whatsapp', 'in_app']).optional(),
  status: z.enum(['queued', 'sent', 'delivered', 'opened', 'clicked', 'failed', 'bounced']).optional(),
  date_from: z.string().datetime().optional(),
  date_to: z.string().datetime().optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(25),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = CommsListSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { client_id, channel, status, date_from, date_to, page, per_page } = parsed.data

  try {
    const supabase = await createClient()

    let query = supabase
      .from('client_communications')
      .select('*', { count: 'exact' })
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })

    if (client_id) query = query.eq('client_id', client_id)
    if (channel) query = query.eq('channel', channel)
    if (status) query = query.eq('status', status)
    if (date_from) query = query.gte('created_at', date_from)
    if (date_to) query = query.lte('created_at', date_to)

    query = query.range((page - 1) * per_page, page * per_page - 1)

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error }, 'client comms GET failed')
      return NextResponse.json({ error: 'Failed to fetch communications' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'client-comms GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

