import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ConsentUpdateSchema = z.object({
  marketing_email: z.boolean(),
  marketing_sms: z.boolean(),
  transactional_only: z.boolean().default(false),
  photo_use_portfolio: z.boolean().default(false),
  photo_use_social: z.boolean().default(false),
  data_retention_years: z.number().int().min(1).max(99).default(7),
})

interface RouteContext {
  params: Promise<{ clientId: string }>
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { clientId } = await params

  try {
    const supabase = await createClient()

    // Verify client belongs to this studio
    const { data: client } = await supabase
      .from('clients')
      .select('id')
      .eq('id', clientId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!client) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    const { data, error } = await supabase
      .from('client_consent_preferences')
      .select('*')
      .eq('client_id', clientId)
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (error) {
      logger.error({ err: error, clientId }, 'consent GET failed')
      return NextResponse.json({ error: 'Failed to fetch consent preferences' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'client-consent GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PUT(request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { clientId } = await params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ConsentUpdateSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()

    // Verify client belongs to this studio
    const { data: client } = await supabase
      .from('clients')
      .select('id')
      .eq('id', clientId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!client) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    // Check existing record to determine version bump
    const { data: existing } = await supabase
      .from('client_consent_preferences')
      .select('consent_version')
      .eq('client_id', clientId)
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    const nextVersion = (existing?.consent_version ?? 0) + 1

    const { data, error } = await supabase
      .from('client_consent_preferences')
      .upsert(
        {
          ...parsed.data,
          studio_id: authUser.studioId,
          client_id: clientId,
          consent_version: nextVersion,
          consented_at: new Date().toISOString(),
        },
        { onConflict: 'client_id' }
      )
      .select()
      .single()

    if (error) {
      logger.error({ err: error, clientId }, 'consent PUT failed')
      return NextResponse.json({ error: 'Failed to save consent preferences' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'client-consent PUT unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

