/** Resolves raw slug strings against the studio tag library */
export function resolveTagSlugs(
  slugs: string[],
  library: ClientTag[]
): ClientTag[] {
  return slugs
    .map((slug) => library.find((t) => t.name.toLowerCase() === slug.toLowerCase() || t.id === slug))
    .filter((t): t is ClientTag => t !== undefined)
}

'use client'

import * as React from 'react'
import { Check, ChevronDown, Search } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { type ClientTag, TagChip } from './TagChip'

interface TagPickerProps {
  tags: ClientTag[]          // full library
  value: string[]            // selected tag names
  onChange: (value: string[]) => void
  placeholder?: string
  className?: string
}

export function TagPicker({ tags, value, onChange, placeholder = 'Select tags…', className }: TagPickerProps) {
  const [open, setOpen] = React.useState(false)
  const [search, setSearch] = React.useState('')

  const filtered = tags.filter((t) =>
    t.name.toLowerCase().includes(search.toLowerCase())
  )

  function toggle(name: string) {
    onChange(
      value.includes(name)
        ? value.filter((v) => v !== name)
        : [...value, name]
    )
  }

  const selectedTags = tags.filter((t) => value.includes(t.name))

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild={false}>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className={cn('h-auto min-h-9 w-full justify-start gap-1.5 flex-wrap px-3 py-1.5 font-normal', className)}
          onClick={() => setOpen(!open)}
        >
          {selectedTags.length === 0 ? (
            <span className="text-muted-foreground text-sm">{placeholder}</span>
          ) : (
            selectedTags.map((tag) => (
              <TagChip
                key={tag.id}
                tag={tag}
                size="xs"
                onRemove={(e) => {
                  void e
                  toggle(tag.name)
                }}
              />
            ))
          )}
          <ChevronDown className="ml-auto h-4 w-4 shrink-0 text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-64 p-0" align="start">
        <div className="flex items-center border-b border-border/40 px-3 py-2">
          <Search className="mr-2 h-3.5 w-3.5 text-muted-foreground shrink-0" />
          <input
            className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            placeholder="Search tags…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="max-h-52 overflow-y-auto p-1">
          {filtered.length === 0 ? (
            <div className="py-4 text-center text-xs text-muted-foreground">No tags found</div>
          ) : (
            filtered.map((tag) => {
              const isSelected = value.includes(tag.name)
              return (
                <button
                  key={tag.id}
                  type="button"
                  onClick={() => toggle(tag.name)}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent/50 transition-colors"
                >
                  <span className={cn(`tag-chip-${tag.color}`, 'h-2 w-2 rounded-full border-0 p-0')} />
                  <span className="flex-1 text-left">{tag.name}</span>
                  {isSelected && <Check className="h-3.5 w-3.5 text-primary shrink-0" />}
                </button>
              )
            })
          )}
        </div>
        {value.length > 0 && (
          <div className="border-t border-border/40 p-1">
            <button
              type="button"
              onClick={() => onChange([])}
              className="w-full rounded-md px-2 py-1.5 text-xs text-muted-foreground hover:bg-accent/50 text-center transition-colors"
            >
              Clear all
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

