              'hover:text-foreground transition-colors duration-150 ease-out',
              'whitespace-nowrap flex items-center gap-1',
              "after:absolute after:bottom-0 after:left-0 after:right-0 after:h-0.5 after:rounded-full after:transition-opacity after:duration-150",
              isActive
                ? 'text-foreground after:bg-primary after:opacity-100'
                : 'after:opacity-0'
            )}
          >
            {tab.label}
            {tab.count !== undefined && tab.count > 0 && (
              <span className="bg-muted text-muted-foreground text-[10px] rounded-full min-w-[1.125rem] h-[1.125rem] flex items-center justify-center px-0.5 tabular-nums">
                {tab.count > 99 ? '99+' : tab.count}
              </span>
            )}
          </Link>
        )
      })}
    </nav>
  )
}

'use client'

import { useState } from 'react'
import { Pin, MoreHorizontal, Trash2, Pencil } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import type { Database } from '@/lib/supabase/types'

type ClientNote = Database['public']['Tables']['client_notes']['Row'] & {
  profiles?: { full_name: string | null } | null
}

type NoteCategory = Database['public']['Tables']['client_notes']['Row']['category']

const CATEGORY_LABELS: Record<NoteCategory, string> = {
  general: 'General',
  medical: 'Medical',
  allergies: 'Allergies',
  skin: 'Skin type',
  emergency_contact: 'Emergency contact',
  aftercare: 'Aftercare',
  preferences: 'Preferences',
  artist_notes: 'Artist notes',
}

interface NoteCardProps {
  note: ClientNote
  onPinToggle: (noteId: string, pinned: boolean) => Promise<void>
  onDelete: (noteId: string) => void
}

export function NoteCard({ note, onPinToggle, onDelete }: NoteCardProps) {
  const [isPinning, setIsPinning] = useState(false)

  async function handlePinToggle() {
    setIsPinning(true)
    try {
      await onPinToggle(note.id, !note.is_pinned)
      toast.success(note.is_pinned ? 'Note unpinned' : 'Note pinned')
    } catch {
      toast.error('Failed to update pin')
    } finally {
      setIsPinning(false)
    }
  }

  const authorName = note.profiles?.full_name ?? 'Unknown'
  const formattedDate = new Date(note.created_at).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })

  return (
    <div
      className={cn(
        'card bg-card border border-border/40 rounded-lg shadow-card',
        note.is_pinned && 'border-l-2 border-l-primary/40'
      )}
    >
      <div className="flex items-center gap-2 px-4 pt-3.5 pb-2">
        <span className={cn('h-2 w-2 rounded-full shrink-0', `note-dot-${note.category}`)} />
        <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex-1">
          {CATEGORY_LABELS[note.category]}
        </span>
        <Button
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={handlePinToggle}
          disabled={isPinning}
          aria-label={note.is_pinned ? 'Unpin note' : 'Pin note'}
        >
          <Pin
            className={cn(
              'h-3.5 w-3.5 transition-colors',
              note.is_pinned ? 'fill-primary text-primary' : 'text-muted-foreground'
            )}
          />
        </Button>
        <DropdownMenu>
          <DropdownMenuTrigger asChild={false}>
            <Button variant="ghost" size="icon" className="h-7 w-7">
              <MoreHorizontal className="h-3.5 w-3.5" />
              <span className="sr-only">More actions</span>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem>
              <Pencil className="mr-2 h-3.5 w-3.5" />
              Edit
            </DropdownMenuItem>
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onClick={() => onDelete(note.id)}
            >
              <Trash2 className="mr-2 h-3.5 w-3.5" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <p className="text-sm text-foreground px-4 pb-3 leading-relaxed">{note.body}</p>

      <p className="text-[11px] text-muted-foreground px-4 pb-3.5">
        {authorName} · {formattedDate}
      </p>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type NoteCategory = Database['public']['Tables']['client_notes']['Row']['category']

const CATEGORIES: { value: NoteCategory; label: string; dotClass: string }[] = [
  { value: 'general', label: 'General', dotClass: 'note-dot-general' },
  { value: 'medical', label: 'Medical', dotClass: 'note-dot-medical' },
  { value: 'allergies', label: 'Allergies', dotClass: 'note-dot-allergies' },
  { value: 'skin', label: 'Skin type', dotClass: 'note-dot-skin' },
  { value: 'emergency_contact', label: 'Emergency contact', dotClass: 'note-dot-emergency_contact' },
  { value: 'aftercare', label: 'Aftercare', dotClass: 'note-dot-aftercare' },
  { value: 'preferences', label: 'Preferences', dotClass: 'note-dot-preferences' },
  { value: 'artist_notes', label: 'Artist notes', dotClass: 'note-dot-artist_notes' },
]

interface AddNoteModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  clientId: string
  onSuccess?: () => void
}

export function AddNoteModal({ open, onOpenChange, clientId, onSuccess }: AddNoteModalProps) {
  const [category, setCategory] = useState<NoteCategory>('general')
  const [body, setBody] = useState('')
  const [isPinned, setIsPinned] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function handleSave() {
    if (body.trim().length < 2) {
      setError('Note must be at least 2 characters.')
      return
    }
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/client-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_id: clientId, category, body: body.trim(), is_pinned: isPinned }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save note')
      }
      toast.success('Note saved')
      setBody('')
      setCategory('general')
      setIsPinned(false)
      onOpenChange(false)
      onSuccess?.()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save note'
      toast.error(message)
      setError(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[480px]">
        <DialogHeader>
          <DialogTitle>Add note</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="note-category">Category</Label>
            <Select value={category} onValueChange={(v) => setCategory(v as NoteCategory)}>
              <SelectTrigger id="note-category">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className="flex items-center gap-2">
                      <span className={cn('h-2 w-2 rounded-full', c.dotClass)} />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="note-body">Note</Label>
            <Textarea
              id="note-body"
              rows={6}
              placeholder="Add a note…"
              value={body}
              onChange={(e) => setBody(e.target.value)}
              className="resize-none"
              aria-invalid={Boolean(error)}
              aria-describedby={error ? 'note-error' : undefined}
            />
            {error && (
              <p id="note-error" role="alert" className="text-xs text-destructive">
                {error}
              </p>
            )}
          </div>

          <div className="flex items-center gap-2">
            <Checkbox
              id="pin-note"
              checked={isPinned}
              onCheckedChange={(v) => setIsPinned(Boolean(v))}
            />
            <Label htmlFor="pin-note" className="text-sm cursor-pointer">
              Pin to overview
            </Label>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving ? 'Saving…' : 'Save note'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { Plus, StickyNote } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { NoteCard } from './NoteCard'
import { AddNoteModal } from './AddNoteModal'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type ClientNote = Database['public']['Tables']['client_notes']['Row'] & {
  profiles?: { full_name: string | null } | null
}
type NoteCategory = Database['public']['Tables']['client_notes']['Row']['category']

const CATEGORY_LABELS: Record<NoteCategory, string> = {
  general: 'General',
  medical: 'Medical',
  allergies: 'Allergies',
  skin: 'Skin type',
  emergency_contact: 'Emergency contact',
  aftercare: 'Aftercare',
  preferences: 'Preferences',
  artist_notes: 'Artist notes',
}

interface ClientNotesTabProps {
  clientId: string
  initialNotes: ClientNote[]
}

export function ClientNotesTab({ clientId, initialNotes }: ClientNotesTabProps) {
  const [notes, setNotes] = useState<ClientNote[]>(initialNotes)
  const [addOpen, setAddOpen] = useState(false)
  const [activeCategory, setActiveCategory] = useState<NoteCategory | 'all'>('all')
  const [loading, setLoading] = useState(false)

  const refetch = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/client-notes?client_id=${clientId}`)
      if (res.ok) {
        const json = await res.json() as { data: ClientNote[] }
        setNotes(json.data ?? [])
      }
    } finally {
      setLoading(false)
    }
  }, [clientId])

  async function handlePinToggle(noteId: string, pinned: boolean) {
    const res = await fetch(`/api/client-notes/${noteId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ is_pinned: pinned }),
    })
    if (!res.ok) throw new Error('Failed to update pin')
    setNotes((prev) =>
      prev.map((n) => (n.id === noteId ? { ...n, is_pinned: pinned } : n))
    )
  }

  async function handleDelete(noteId: string) {
    const res = await fetch(`/api/client-notes/${noteId}`, { method: 'DELETE' })
    if (!res.ok) {
      toast.error('Failed to delete note')
      return
    }
    toast.success('Note deleted')
    setNotes((prev) => prev.filter((n) => n.id !== noteId))
  }

  const filtered = notes.filter((n) => activeCategory === 'all' || n.category === activeCategory)
  const pinned = filtered.filter((n) => n.is_pinned).sort((a, b) => b.updated_at.localeCompare(a.updated_at))
  const unpinned = filtered.filter((n) => !n.is_pinned).sort((a, b) => b.created_at.localeCompare(a.created_at))

  const categories = [...new Set(notes.map((n) => n.category))] as NoteCategory[]

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between">
        <h2 className="text-base font-semibold">Notes</h2>
        <Button size="sm" onClick={() => setAddOpen(true)}>
          <Plus className="mr-2 h-4 w-4" />
          Add note
        </Button>
      </div>

      {/* Category filter */}
      {categories.length > 1 && (
        <div className="flex flex-wrap gap-1.5">
          <Button
            variant={activeCategory === 'all' ? 'default' : 'outline'}
            size="sm"
            className="h-7 text-xs"
            onClick={() => setActiveCategory('all')}
          >
            All
          </Button>
          {categories.map((cat) => (
            <Button
              key={cat}
              variant={activeCategory === cat ? 'default' : 'outline'}
              size="sm"
              className="h-7 text-xs"
              onClick={() => setActiveCategory(cat)}
            >
              <span className={cn('h-2 w-2 rounded-full mr-1.5', `note-dot-${cat}`)} />
              {CATEGORY_LABELS[cat]}
            </Button>
          ))}
        </div>
      )}

      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-28 w-full rounded-lg" />
          ))}
        </div>
      ) : notes.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 gap-4 text-center">
          <div className="rounded-xl bg-muted/50 p-4">
            <StickyNote className="h-10 w-10 text-muted-foreground/50" />
          </div>
          <div className="space-y-1">
            <h3 className="text-sm font-medium">No notes yet</h3>
            <p className="text-sm text-muted-foreground max-w-xs">
              Add your first note for context — allergies, preferences, or anything useful.
            </p>
          </div>
          <Button size="sm" onClick={() => setAddOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Add note
          </Button>
        </div>
      ) : (
        <>
          {pinned.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                <div className="h-px flex-1 bg-border/40" />
                Pinned
                <div className="h-px flex-1 bg-border/40" />
              </div>
              {pinned.map((note) => (
                <NoteCard
                  key={note.id}
                  note={note}
                  onPinToggle={handlePinToggle}
                  onDelete={handleDelete}
                />
              ))}
            </div>
          )}

          {unpinned.length > 0 && (
            <div className="space-y-2">
              {pinned.length > 0 && (
                <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  <div className="h-px flex-1 bg-border/40" />
                  All notes
                  <div className="h-px flex-1 bg-border/40" />
                </div>
              )}
              {unpinned.map((note) => (
                <NoteCard
                  key={note.id}
                  note={note}
                  onPinToggle={handlePinToggle}
                  onDelete={handleDelete}
                />
              ))}
            </div>
          )}
        </>
      )}

      <AddNoteModal
        open={addOpen}
        onOpenChange={setAddOpen}
        clientId={clientId}
        onSuccess={refetch}
      />
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { X, ChevronLeft, ChevronRight, Download } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Dialog, DialogContent } from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

export interface LightboxPhoto {
  id: string
  storagePath: string
  kind: string
  bookingDate?: string
  serviceName?: string
  artistName?: string
  caption?: string | null
}

interface PhotoLightboxProps {
  photos: LightboxPhoto[]
  initialIndex: number
  open: boolean
  onOpenChange: (open: boolean) => void
  getSignedUrl: (storagePath: string) => Promise<string>
}

export function PhotoLightbox({
  photos,
  initialIndex,
  open,
  onOpenChange,
  getSignedUrl,
}: PhotoLightboxProps) {
  const [index, setIndex] = useState(initialIndex)
  const [url, setUrl] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  const current = photos[index]

  const loadPhoto = useCallback(async (path: string) => {
    setLoading(true)
    setUrl(null)
    try {
      const signed = await getSignedUrl(path)
      setUrl(signed)
    } finally {
      setLoading(false)
    }
  }, [getSignedUrl])

  useEffect(() => {
    if (open && current) {
      setIndex(initialIndex)
      void loadPhoto(current.storagePath)
    }
  }, [open, initialIndex]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (open && current) {
      void loadPhoto(current.storagePath)
    }
  }, [index, open, current, loadPhoto])

  function goNext() {
    setIndex((i) => (i + 1) % photos.length)
  }

  function goPrev() {
    setIndex((i) => (i - 1 + photos.length) % photos.length)
  }

  useEffect(() => {
    if (!open) return
    function handleKey(e: KeyboardEvent) {
      if (e.key === 'ArrowRight') goNext()
      else if (e.key === 'ArrowLeft') goPrev()
      else if (e.key === 'd' || e.key === 'D') handleDownload()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [open, photos.length]) // eslint-disable-line react-hooks/exhaustive-deps

  function handleDownload() {
    if (!url || !current) return
    const a = document.createElement('a')
    a.href = url
    a.download = `photo-${current.id}.jpg`
    a.click()
  }

  if (!current) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="lightbox-overlay max-w-none w-screen h-screen p-0 rounded-none border-0 flex flex-col items-center justify-center"
        aria-label="Photo lightbox"
      >
        {/* Close button */}
        <Button
          variant="ghost"
          size="icon"
          className="absolute top-4 right-4 h-9 w-9 text-white/70 hover:text-white hover:bg-white/10 z-50"
          onClick={() => onOpenChange(false)}
        >
          <X className="h-5 w-5" />
          <span className="sr-only">Close</span>
        </Button>

        {/* Prev */}
        {photos.length > 1 && (
          <Button
            variant="ghost"
            size="icon"
            className="absolute left-4 top-1/2 -translate-y-1/2 h-12 w-12 text-white/70 hover:text-white hover:bg-white/10 z-50"
            onClick={goPrev}
          >
            <ChevronLeft className="h-6 w-6" />
            <span className="sr-only">Previous</span>
          </Button>
        )}

        {/* Photo */}
        <div className="flex-1 flex items-center justify-center w-full px-20 py-16">
          {loading && <Skeleton className="max-h-[85vh] max-w-[85vw] w-[600px] h-[400px]" />}
          {url && !loading && (
            <img
              src={url}
              alt={current.caption ?? `Photo (${current.kind})`}
              className={cn(
                'max-h-[85vh] max-w-[85vw] object-contain mx-auto rounded-md',
                'touch-action-pan-y'
              )}
              draggable={false}
            />
          )}
        </div>

        {/* Next */}
        {photos.length > 1 && (
          <Button
            variant="ghost"
            size="icon"
            className="absolute right-4 top-1/2 -translate-y-1/2 h-12 w-12 text-white/70 hover:text-white hover:bg-white/10 z-50"
            onClick={goNext}
          >
            <ChevronRight className="h-6 w-6" />
            <span className="sr-only">Next</span>
          </Button>
        )}

        {/* Meta strip */}
        <div className="absolute bottom-0 left-0 right-0 bg-background/80 backdrop-blur-sm flex items-center justify-between px-6 py-3">
          <span className="text-sm text-muted-foreground">
            {[current.bookingDate, current.serviceName, current.artistName, current.kind]
              .filter(Boolean)
              .join(' · ')}
          </span>
          <div className="flex gap-2">
            <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-foreground" onClick={handleDownload}>
              <Download className="mr-2 h-4 w-4" />
              Download
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}
